313	  }
314	}
315	
316	@media (max-width: 375px) {
317	  .container {
318	    padding: 0.75rem; /* Minimal padding on small phones */
319	  }
320	  .kpi-card, .chart-card {
321	    padding: 1rem; /* Reduced card padding */
322	  }
323	  .filter-toolbar {
324	    flex-direction: column; /* Stack filters vertically */
325	    align-items: stretch;
326	  }
327	}
