                if (!chartArea) return c.fillGradStart;
                var gradient = context.chart.ctx.createLinearGradient(chartArea.left, 0, chartArea.right, 0);
                gradient.addColorStop(0, c.fillGradStart);
                gradient.addColorStop(0.6, c.fillGradStart);
                gradient.addColorStop(1, c.fillGradEnd);
                return gradient;
              },
              borderWidth: 6,
              pointRadius: 0,
              pointHoverRadius: 10,
              pointHoverBackgroundColor: c.accent,
              pointHoverBorderColor: '#fff',
              pointHoverBorderWidth: 4,
              tension: 0.35,
              fill: true,
              order: 2
            },
            {
              label: '1.5 °C Threshold',
              data: new Array(tempLabels.length).fill(1.5),
              borderColor: c.thresholdRed,
              borderWidth: 4,
              borderDash: [20, 16],
              pointRadius: 0,
              pointHoverRadius: 0,
              fill: false,
              order: 1
            },
            {
              label: 'IPCC 1850–1900 Baseline Period',
              data: tempLabels.map(function(l) {
                var yr = parseInt(l);
                return (yr >= 1850 && yr <= 1900) ? tempData[tempLabels.indexOf(l)] : null;
