          plugins: {
            tooltip: {
              enabled: true,
              backgroundColor: c.surface,
              titleColor: c.text,
              bodyColor: c.textSecondary,
              borderColor: c.border,
              borderWidth: 1,
              padding: 18,
              cornerRadius: 8,
              titleFont: { size: 28, family: 'Inter', weight: '600' },
              bodyFont: { size: 24, family: 'Inter' },
              callbacks: {
                label: function(ctx) {
                  if (ctx.datasetIndex === 1) return '1.5 °C Paris Threshold';
                  if (ctx.datasetIndex === 2) return '';
                  return 'Anomaly: +' + ctx.parsed.y.toFixed(2) + ' °C';
                }
              }
            },
            legend: {
              display: true,
              position: 'top',
              labels: {
                color: c.text,
                font: { size: 30, family: 'Inter' },
                padding: 32,
                usePointStyle: true,
                pointStyleWidth: 16,
                filter: function(item) { return item.datasetIndex !== 2; }
              }
            }
          },
          layout: {
            padding: { top: 24, right: 24, bottom: 24, left: 24 }
          },
          scales: {
            x: {
              title: {
                display: true,
                text: 'Year',
                color: c.textSecondary,
                font: { size: 32, family: 'Inter', weight: '500' }
              },
              ticks: {
                color: c.textSecondary,
                font: { size: 28, family: 'Inter' },
                maxRotation: 0,
                maxTicksLimit: 17,
                callback: function(val, idx) { return (idx % 2 === 0) ? tempLabels[idx] : ''; }
