    .milestone {
      flex: 1;
      background: var(--surface-hover);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 16px 20px;
      text-align: center;
    }
    .milestone-period {
      font-size: 26px;
      font-weight: 600;
      color: var(--accent-secondary);
      letter-spacing: 0.03em;
    }
    .milestone-desc {
      font-size: 24px;
      color: var(--text-secondary);
      margin-top: 4px;
      line-height: 1.3;
    }

    /* Implication cards */
    .impl-list {
      display: flex; flex-direction: column;
      gap: 16px;
      margin-top: 20px;
    }
    .impl-item {
      display: flex; align-items: flex-start;
      gap: 20px;
      font-size: 34px;
      line-height: 1.45;
      color: var(--text);
    }
    .impl-marker {
      width: 12px; height: 12px;
      border-radius: 50%;
      background: var(--accent);
      margin-top: 16px;
      flex-shrink: 0;
    }

    .method-item {
      display: flex; gap: 16px;
      align-items: flex-start;
      margin-bottom: 20px;
    }
    .method-icon {
      width: 52px; height: 52px;
      border-radius: 8px;
      background: var(--accent-secondary);
      color: #fff;
      display: flex; align-items: center;
      justify-content: center;
      font-size: 28px;
      font-weight: 700;
      flex-shrink: 0;
    }
    .method-text {
      font-size: 34px;
      line-height: 1.45;
      color: var(--text);
    }

    /* Footer */
    .poster-footer {
      display: flex; justify-content: space-between;
      align-items: center;
      padding-top: 28px;
      border-top: 2px solid var(--border);
    }
    .footer-ref {
      font-size: 30px;
      color: var(--text-secondary);
      font-style: italic;
    }

    .sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); }
  </style>
</head>
