586	    // === Chart.js Integration ===
587	    var ChartManager = {
588	      charts: new Map(),
589	      safeInit: function(canvasId, config) {
590	        if (typeof Chart === 'undefined') { console.error('Chart.js library not loaded'); return null; }
591	        try {
592	          if (this.charts.has(canvasId)) { this.charts.get(canvasId).destroy(); this.charts.delete(canvasId); }
593	          var ctx = document.getElementById(canvasId);
594	          if (!ctx) { console.error('Canvas element not found: ' + canvasId); return null; }
595	          if (ctx.chart) { ctx.chart.destroy(); delete ctx.chart; }
596	          ctx.setAttribute('role', 'img');
597	          if (!ctx.getAttribute('aria-label')) { ctx.setAttribute('aria-label', 'Chart visualization'); }
598	          var chart = new Chart(ctx, config);
599	          this.charts.set(canvasId, chart);
600	          return chart;
601	        } catch (error) { console.error('Chart init failed for ' + canvasId + ':', error); return null; }
602	      },
603	      updateTheme: function() {
604	        if (typeof Chart === 'undefined') return;
605	        this.charts.forEach(function(chart) { try { chart.update(); } catch(e) { console.error('Chart theme update failed:', e); } });
606	      },
