612	
613	    var chartsBuilt = false;
614	
615	    function getChartColors() {
616	      var isDark = document.documentElement.classList.contains('theme-dark');
617	      return {
618	        text: isDark ? '#e8eaed' : '#1a2332',
619	        textSecondary: isDark ? '#8899b0' : '#5a6d80',
620	        border: isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.08)',
621	        surface: isDark ? '#0d1a2d' : '#ffffff',
622	        accent: isDark ? '#e8784a' : '#d46530',
623	        accentBlue: isDark ? '#4a90d9' : '#256ea6',
624	        gridLine: isDark ? 'rgba(255,255,255,0.04)' : 'rgba(0,0,0,0.05)',
