    print(f'  ... y-range: {min(p[1] for p in coral)}-{max(p[1] for p in coral)}')

print(f'Ocean blue pixels: {len(ocean)}')
if ocean:
    for p in ocean[:5]: print(f'  ({p[0]}, {p[1]}): RGB{p[2]}')
    print(f'  ... y-range: {min(p[1] for p in ocean)}-{max(p[1] for p in ocean)}')

